-- The Moroccan NGAP (Nomenclature générale des actes professionnels), fixed by the
-- health minister's arrêté n° 177-06 of 27 January 2006, for the acts a dental clinic
-- writes on a care form: Titre III chapters V to VIII (mouth and pharynx, jaws, teeth
-- and gums, maxillofacial prosthesis), the dental assimilations of chapter IX, and the
-- consultation and visit letters of the first part.
--
-- Transcribed from the published text and checked against its pages. National
-- reference data: the same for every clinic, so it has no practice_id. A clinic links
-- its own catalogue to it through treatments.act_code.
--
-- * code: the row number in the text (D500...). Its first letter numbers the Titre
--   (D = Titre III), it is not the key letter.
-- * key_letter: what the care form shows before the coefficient (article 2). D for
--   acts by a chirurgien-dentiste or médecin dentiste; a médecin uses K instead.
-- * coefficient / anesthesia_coefficient: the text's two columns. The second is the
--   anaesthesia cotation (article 22-3; D722 and D723 are introduced as "les cotations
--   à retenir concernant cette anesthésie" and carry only that column). NULL where the
--   text gives none: a bridge element (D757), a facial prosthesis priced on quote (D816).
-- * prior_agreement: article 5 (orthodontic treatment, assimilated acts, D816).
-- * The ten assimilations have no number in the text; ASD01-ASD10 are OrthoFlow's own
--   codes, and assimilated_to names the act they are assimilated to where the text does.
-- A few obvious misprints in the source were corrected in labels (hypopharinx,
-- intrarmaxillaire, sushyoïdienne); no coefficient was changed.

CREATE TABLE ngap_acts (
    code                   VARCHAR(10)  PRIMARY KEY,
    key_letter             VARCHAR(4)   NOT NULL,
    coefficient            NUMERIC(8,2) CHECK (coefficient > 0),
    anesthesia_coefficient NUMERIC(8,2) CHECK (anesthesia_coefficient > 0),
    label                  TEXT         NOT NULL,
    chapter                VARCHAR(120) NOT NULL,
    section                VARCHAR(200),
    notes                  TEXT,
    prior_agreement        BOOLEAN      NOT NULL DEFAULT FALSE,
    assimilated_to         VARCHAR(10)  REFERENCES ngap_acts(code),
    sort_order             INT          NOT NULL
);

CREATE INDEX idx_ngap_acts_search ON ngap_acts (lower(label) text_pattern_ops);

